#pragma once

// Copy to include/secrets.h (kept out of git) and fill in.

namespace secrets {

// The ESP32 only connects to 2.4 GHz networks
constexpr char WIFI_SSID[] = "network-name";
constexpr char WIFI_PASSWORD[] = "network-password";

// Client ID of the app on the Spotify Developer Dashboard. The client secret doesn't
// go on the device: the token is refreshed with PKCE, which only uses the client id.
constexpr char SPOTIFY_CLIENT_ID[] = "your-client-id";

// Generated by: python tools/get_refresh_token.py (PKCE flow)
constexpr char SPOTIFY_REFRESH_TOKEN[] = "your-refresh-token";

// Playlist for songs with no clear destination (the same fallback_playlist_id as
// config/config.json). Empty hides the "Fallback" option.
constexpr char FALLBACK_PLAYLIST_ID[] = "";

// Last.fm API key (the same LASTFM_API_KEY as config/settings.py). With no
// direct match, the suggestions come from similar artists. Empty turns it off.
constexpr char LASTFM_API_KEY[] = "";

}  // namespace secrets
